package model

// SiteConfig is the concise operator-authored v0.3 configuration. Expanded
// components and resolved module state are generated by the composition layer
// and are deliberately not accepted from site.yml.
type SiteConfig struct {
	APIVersion       string                  `yaml:"api_version"`
	PlatformVersion  string                  `yaml:"platform_version"`
	SchemaVersion    int                     `yaml:"schema_version"`
	StorageProfile   string                  `yaml:"storage_profile"`
	StorageDevice    string                  `yaml:"storage_device,omitempty"`
	Gateway          Gateway                 `yaml:"gateway"`
	ProxmoxNode      string                  `yaml:"proxmox_node"`
	BootstrapAddress string                  `yaml:"bootstrap_address,omitempty"`
	SSHIdentityFile  string                  `yaml:"ssh_identity_file,omitempty"`
	PhysicalNetwork  PhysicalNetwork         `yaml:"physical_network"`
	TestedVersions   TestedVersions          `yaml:"tested_versions"`
	Network          Network                 `yaml:"network"`
	PKI              PKIMetadata             `yaml:"pki"`
	SecretMetadata   SecretMetadata          `yaml:"secret_metadata"`
	Ownership        OwnershipPolicy         `yaml:"ownership"`
	Modules          map[string]ModuleConfig `yaml:"modules,omitempty"`
}

func ConfigFromSite(s Site) SiteConfig {
	return SiteConfig{
		APIVersion: s.APIVersion, PlatformVersion: s.PlatformVersion,
		SchemaVersion: s.SchemaVersion, StorageProfile: s.StorageProfile,
		StorageDevice: s.StorageDevice, Gateway: s.Gateway,
		ProxmoxNode: s.ProxmoxNode, BootstrapAddress: s.BootstrapAddress,
		SSHIdentityFile: s.SSHIdentityFile, PhysicalNetwork: s.PhysicalNetwork,
		TestedVersions: s.TestedVersions, Network: s.Network, PKI: s.PKI,
		SecretMetadata: s.SecretMetadata, Ownership: s.Ownership,
		Modules: cloneModuleConfig(s.ModuleConfig),
	}
}

func (c SiteConfig) BaseSite() Site {
	s := NewSite(c.SecretMetadata.InstallationID, c.SecretMetadata.AgeRecipient, c.Gateway.Mode)
	s.APIVersion = c.APIVersion
	s.PlatformVersion = c.PlatformVersion
	s.SchemaVersion = c.SchemaVersion
	s.StorageProfile = c.StorageProfile
	s.StorageDevice = c.StorageDevice
	s.Gateway = c.Gateway
	s.ProxmoxNode = c.ProxmoxNode
	s.BootstrapAddress = c.BootstrapAddress
	s.SSHIdentityFile = c.SSHIdentityFile
	s.PhysicalNetwork = c.PhysicalNetwork
	s.TestedVersions = c.TestedVersions
	s.Network = c.Network
	s.PKI = c.PKI
	s.SecretMetadata = c.SecretMetadata
	s.Ownership = c.Ownership
	s.ModuleConfig = cloneModuleConfig(c.Modules)
	return s
}

func (c SiteConfig) Validate() error {
	return c.BaseSite().Validate()
}

func cloneModuleConfig(input map[string]ModuleConfig) map[string]ModuleConfig {
	if len(input) == 0 {
		return nil
	}
	output := make(map[string]ModuleConfig, len(input))
	for name, config := range input {
		var enabled *bool
		if config.Enabled != nil {
			value := *config.Enabled
			enabled = &value
		}
		output[name] = ModuleConfig{Enabled: enabled}
	}
	return output
}
